<script setup>
// Perfil editable del emprendimiento: datos, redes, formas de pago, locales y horarios.
import { ref, computed, onMounted, onBeforeUnmount } from "vue";
import { useRouter } from "vue-router";
import { supabase } from "../../lib/supabaseClient";
import { uploadEntrepreneurLogo, deleteImage, getStoragePathFromPublicUrl } from "../../lib/storage";
import BusinessNav from "../../components/business/BusinessNav.vue";
import LocationPicker from "../../components/maps/LocationPicker.vue";
import SubscriptionCard from "../../components/shared/SubscriptionCard.vue";
import DemoSubscriptionModal from "../../components/shared/DemoSubscriptionModal.vue";
import { subscriptionIsActive, activateDemoSubscription } from "../../lib/subscription";
const router=useRouter(); const entrepreneur=ref(null),locations=ref([]);const loading=ref(true),loadError=ref(""),saving=ref(false),locationSaving=ref(false),logoutLoading=ref(false),paymentLoading=ref(false);const showEditor=ref(false),showLocationEditor=ref(false),showPayment=ref(false);const logoFile=ref(null),logoPreview=ref("");
const form=ref({businessName:"",phone:"",description:"",department:"",district:"",instagramUrl:"",facebookUrl:"",tiktokUrl:"",websiteUrl:"",paymentMethods:[],serviceTags:[]});
const locationForm=ref({id:"",name:"",address:"",latitude:null,longitude:null,isPrimary:false,active:true,hours:[]});
const currentPassword=ref(""),newPassword=ref(""),confirmPassword=ref("");const departments=["Ahuachapán","Cabañas","Chalatenango","Cuscatlán","La Libertad","La Paz","La Unión","Morazán","San Miguel","San Salvador","San Vicente","Santa Ana","Sonsonate","Usulután"];
const paymentOptions=["Efectivo","Tarjeta","Transferencia"];
const serviceOptions=["Retiro en local","Entrega a domicilio","Envíos nacionales","Pedidos personalizados","Reserva previa"];
const weekdays=["Lunes","Martes","Miércoles","Jueves","Viernes","Sábado","Domingo"];
const initials=computed(()=>String(entrepreneur.value?.businessName||"Thrive").trim().split(/\s+/).slice(0,2).map(w=>w[0]?.toUpperCase()).join(""));
const subscription=computed(()=>({status:entrepreneur.value?.subscriptionStatus||"inactive",price:Number(entrepreneur.value?.subscriptionPrice)||4.99,startedAt:entrepreneur.value?.subscriptionStartedAt||null,expiresAt:entrepreneur.value?.subscriptionExpiresAt||null}));
const hasActiveSubscription=computed(()=>subscriptionIsActive(subscription.value));
function emptyHours(){return weekdays.map((_,weekday)=>({weekday,isClosed:weekday===6,openTime:weekday===5?"09:00":"08:00",closeTime:weekday===5?"14:00":"18:00"}));}
function toggleArray(key,value){const arr=form.value[key];form.value[key]=arr.includes(value)?arr.filter(x=>x!==value):[...arr,value];}
function clearPasswords(){currentPassword.value="";newPassword.value="";confirmPassword.value="";}
function openEditor(){form.value={businessName:entrepreneur.value.businessName,phone:entrepreneur.value.phone,description:entrepreneur.value.description,department:entrepreneur.value.department,district:entrepreneur.value.district,instagramUrl:entrepreneur.value.instagramUrl,facebookUrl:entrepreneur.value.facebookUrl,tiktokUrl:entrepreneur.value.tiktokUrl,websiteUrl:entrepreneur.value.websiteUrl,paymentMethods:[...entrepreneur.value.paymentMethods],serviceTags:[...entrepreneur.value.serviceTags]};logoFile.value=null;logoPreview.value=entrepreneur.value.logoUrl;clearPasswords();showEditor.value=true;document.body.style.overflow="hidden";}
function closeEditor(){showEditor.value=false;logoFile.value=null;logoPreview.value="";clearPasswords();document.body.style.overflow="";}
function handleLogo(e){const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith("image/")||f.size>5*1024*1024){alert("Selecciona una imagen válida de hasta 5 MB.");return;}logoFile.value=f;const reader=new FileReader();reader.onload=x=>logoPreview.value=x.target.result;reader.readAsDataURL(f);}
function openLocation(location=null){if(location){locationForm.value={id:location.id,name:location.name,address:location.address,latitude:location.latitude,longitude:location.longitude,isPrimary:location.isPrimary,active:location.active,hours:weekdays.map((_,weekday)=>{const h=location.hours.find(x=>x.weekday===weekday);return h?{weekday,isClosed:h.is_closed,openTime:String(h.open_time||"08:00").slice(0,5),closeTime:String(h.close_time||"18:00").slice(0,5)}:emptyHours()[weekday];})};}else locationForm.value={id:"",name:"",address:"",latitude:null,longitude:null,isPrimary:locations.value.length===0,active:true,hours:emptyHours()};showLocationEditor.value=true;document.body.style.overflow="hidden";}
function closeLocation(){showLocationEditor.value=false;document.body.style.overflow="";}
async function loadLocations(userId){const{data,error}=await supabase.from("entrepreneur_locations").select(`id,name,address,latitude,longitude,is_primary,active,entrepreneur_location_hours(weekday,is_closed,open_time,close_time)`).eq("entrepreneur_id",userId).order("is_primary",{ascending:false});if(error)throw error;locations.value=(data||[]).map(l=>({id:l.id,name:l.name,address:l.address,latitude:Number(l.latitude),longitude:Number(l.longitude),isPrimary:Boolean(l.is_primary),active:Boolean(l.active),hours:(l.entrepreneur_location_hours||[]).sort((a,b)=>a.weekday-b.weekday)}));}
async function load(){loading.value=true;loadError.value="";try{const{data:{user},error:uErr}=await supabase.auth.getUser();if(uErr||!user)return router.replace({name:"Access"});const[{data:b,error:bErr},{data:p,error:pErr}]=await Promise.all([supabase.from("entrepreneurs").select(`id,business_name,description,department,district,logo_url,instagram_url,facebook_url,tiktok_url,website_url,payment_methods,service_tags,subscription_status,subscription_price,subscription_started_at,subscription_expires_at`).eq("id",user.id).single(),supabase.from("profiles").select("phone").eq("id",user.id).single()]);if(bErr)throw bErr;if(pErr)throw pErr;entrepreneur.value={id:b.id,businessName:b.business_name||"Mi emprendimiento",phone:p.phone||"",email:user.email||"",description:b.description||"",department:b.department||"",district:b.district||"",logoUrl:b.logo_url||"",instagramUrl:b.instagram_url||"",facebookUrl:b.facebook_url||"",tiktokUrl:b.tiktok_url||"",websiteUrl:b.website_url||"",paymentMethods:b.payment_methods||[],serviceTags:b.service_tags||[],subscriptionStatus:b.subscription_status||"inactive",subscriptionPrice:Number(b.subscription_price)||4.99,subscriptionStartedAt:b.subscription_started_at||null,subscriptionExpiresAt:b.subscription_expires_at||null};await loadLocations(user.id);}catch(e){console.error(e);loadError.value="No fue posible cargar tu perfil.";}finally{loading.value=false;}}
async function saveProfile(){if(saving.value||!form.value.businessName.trim())return;saving.value=true;let uploaded=null;try{const{data:{user}}=await supabase.auth.getUser();if(!user)throw new Error("Sesión no válida");const wantsPassword=currentPassword.value||newPassword.value||confirmPassword.value;if(wantsPassword){if(!currentPassword.value||!newPassword.value||!confirmPassword.value)throw new Error("Completa los tres campos de contraseña.");if(newPassword.value.length<8)throw new Error("La nueva contraseña debe tener al menos 8 caracteres.");if(newPassword.value!==confirmPassword.value)throw new Error("Las nuevas contraseñas no coinciden.");const{error}=await supabase.auth.signInWithPassword({email:user.email,password:currentPassword.value});if(error)throw new Error("La contraseña actual es incorrecta.");}const oldPath=getStoragePathFromPublicUrl(entrepreneur.value.logoUrl);let logoUrl=entrepreneur.value.logoUrl||null;if(logoFile.value){uploaded=await uploadEntrepreneurLogo(user.id,logoFile.value);logoUrl=uploaded.publicUrl;}const{error:bErr}=await supabase.from("entrepreneurs").update({business_name:form.value.businessName.trim(),description:form.value.description.trim(),department:form.value.department||null,district:form.value.district.trim()||null,logo_url:logoUrl,instagram_url:form.value.instagramUrl.trim()||null,facebook_url:form.value.facebookUrl.trim()||null,tiktok_url:form.value.tiktokUrl.trim()||null,website_url:form.value.websiteUrl.trim()||null,payment_methods:form.value.paymentMethods,service_tags:form.value.serviceTags}).eq("id",user.id);if(bErr)throw bErr;
        // El emprendedor no tiene nombre personal en el formulario: full_name se mantiene vacío.
        const{error:pErr}=await supabase.from("profiles").update({full_name:null,phone:form.value.phone.trim(),avatar_url:logoUrl}).eq("id",user.id);if(pErr)throw pErr;
        // También limpiamos metadatos antiguos que pudieran mostrarse como Display name.
        await supabase.auth.updateUser({data:{full_name:null,display_name:null,name:null}});
        if(uploaded?.path&&oldPath&&oldPath!==uploaded.path){try{await deleteImage(oldPath);}catch{}}
        if(wantsPassword){const{error}=await supabase.auth.updateUser({password:newPassword.value});if(error)throw error;}
        entrepreneur.value={...entrepreneur.value,businessName:form.value.businessName.trim(),phone:form.value.phone.trim(),description:form.value.description.trim(),department:form.value.department,district:form.value.district.trim(),logoUrl:logoUrl||"",instagramUrl:form.value.instagramUrl.trim(),facebookUrl:form.value.facebookUrl.trim(),tiktokUrl:form.value.tiktokUrl.trim(),websiteUrl:form.value.websiteUrl.trim(),paymentMethods:[...form.value.paymentMethods],serviceTags:[...form.value.serviceTags]};closeEditor();alert("Perfil actualizado correctamente.");
    }catch(e){console.error(e);if(uploaded?.path){try{await deleteImage(uploaded.path);}catch{}}alert(e.message||"No fue posible guardar los cambios.");}finally{saving.value=false;}}
async function saveLocation(){if(locationSaving.value)return;if(!locationForm.value.name.trim()||!locationForm.value.address.trim()||!Number.isFinite(Number(locationForm.value.latitude))||!Number.isFinite(Number(locationForm.value.longitude))){alert("Completa el nombre, dirección y coloca el punto exacto en el mapa.");return;}locationSaving.value=true;try{const{data:{user}}=await supabase.auth.getUser();if(!user)throw new Error("Sesión no válida");if(locationForm.value.isPrimary){const{error}=await supabase.from("entrepreneur_locations").update({is_primary:false}).eq("entrepreneur_id",user.id).eq("is_primary",true);if(error)throw error;}const payload={entrepreneur_id:user.id,name:locationForm.value.name.trim(),address:locationForm.value.address.trim(),latitude:Number(locationForm.value.latitude),longitude:Number(locationForm.value.longitude),is_primary:Boolean(locationForm.value.isPrimary),active:Boolean(locationForm.value.active)};let locationId=locationForm.value.id;if(locationId){const{error}=await supabase.from("entrepreneur_locations").update(payload).eq("id",locationId);if(error)throw error;}else{const{data,error}=await supabase.from("entrepreneur_locations").insert(payload).select("id").single();if(error)throw error;locationId=data.id;}const{error:delErr}=await supabase.from("entrepreneur_location_hours").delete().eq("location_id",locationId);if(delErr)throw delErr;const rows=locationForm.value.hours.map(h=>({location_id:locationId,weekday:h.weekday,is_closed:Boolean(h.isClosed),open_time:h.isClosed?null:h.openTime,close_time:h.isClosed?null:h.closeTime}));const{error:hErr}=await supabase.from("entrepreneur_location_hours").insert(rows);if(hErr)throw hErr;await loadLocations(user.id);closeLocation();}catch(e){console.error(e);alert(e.message||"No fue posible guardar el local.");}finally{locationSaving.value=false;}}
async function deleteLocation(location){if(!confirm(`¿Eliminar ${location.name}?`))return;try{const{error}=await supabase.from("entrepreneur_locations").delete().eq("id",location.id);if(error)throw error;locations.value=locations.value.filter(l=>l.id!==location.id);}catch(e){console.error(e);alert("No fue posible eliminar el local.");}}
function openPayment(){showPayment.value=true;document.body.style.overflow="hidden";}function closePayment(){if(paymentLoading.value)return;showPayment.value=false;document.body.style.overflow="";}async function confirmDemoPayment(){paymentLoading.value=true;try{const result=await activateDemoSubscription();entrepreneur.value={...entrepreneur.value,subscriptionStatus:result.status,subscriptionPrice:result.price,subscriptionStartedAt:result.startedAt,subscriptionExpiresAt:result.expiresAt};closePayment();}catch(e){alert(e.message||"No fue posible activar el plan.");}finally{paymentLoading.value=false;}}
async function logout(){logoutLoading.value=true;try{await supabase.auth.signOut({scope:"local"});router.replace({name:"Access"});}finally{logoutLoading.value=false;}}
function esc(e){if(e.key!=="Escape")return;if(showLocationEditor.value)closeLocation();else if(showEditor.value)closeEditor();else if(showPayment.value)closePayment();}
onMounted(()=>{load();document.addEventListener("keydown",esc)});onBeforeUnmount(()=>{document.removeEventListener("keydown",esc);document.body.style.overflow="";});
</script>
<template>
<div class="min-h-screen bg-[#F8FBFC] pb-[78px] text-gray-700 lg:pb-10"><BusinessNav active="profile" :business-name="entrepreneur?.businessName||'Thrive'"/><main v-if="loading" class="py-24 text-center"><div class="mx-auto h-9 w-9 animate-spin rounded-full border-4 border-[#CAF0F8] border-t-[#00B4D8]"></div></main><main v-else-if="loadError" class="mx-auto max-w-xl px-5 py-24 text-center">{{ loadError }}</main><main v-else-if="entrepreneur" class="mx-auto max-w-[1450px] px-3 py-5 sm:px-5 lg:px-8"><section class="rounded-[28px] bg-white p-5 shadow-sm sm:p-7"><div class="flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between"><div class="flex flex-col items-center gap-5 text-center sm:flex-row sm:text-left"><img v-if="entrepreneur.logoUrl" :src="entrepreneur.logoUrl" class="h-24 w-24 rounded-[26px] object-cover ring-4 ring-[#EAF9FC]"><div v-else class="flex h-24 w-24 items-center justify-center rounded-[26px] bg-[#EAF9FC] text-xl font-black text-[#0077B6]">{{ initials }}</div><div><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Perfil del emprendimiento</p><h1 class="mt-1 text-2xl font-black sm:text-3xl">{{ entrepreneur.businessName }}</h1><p class="mt-1 text-sm text-gray-400">{{ entrepreneur.email }}</p><p class="mt-1 text-sm text-gray-400">{{ entrepreneur.phone||'Teléfono no registrado' }}</p></div></div><div class="flex flex-col gap-2 sm:flex-row"><button class="rounded-[15px] border border-[#00B4D8] px-5 py-3 text-sm font-black text-[#0077B6]" @click="openEditor">Editar perfil</button><button :disabled="logoutLoading" class="rounded-[15px] bg-red-50 px-5 py-3 text-sm font-black text-red-600" @click="logout">Cerrar sesión</button></div></div></section><SubscriptionCard class="mt-5" :subscription="subscription" :loading="paymentLoading" @subscribe="openPayment"/><section class="mt-5 grid gap-4 lg:grid-cols-2"><article class="rounded-[26px] bg-white p-5 shadow-sm"><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Presentación</p><p class="mt-3 whitespace-pre-line text-sm leading-7 text-gray-500">{{ entrepreneur.description||'Agrega una descripción para presentar tu emprendimiento.' }}</p><div class="mt-4 flex flex-wrap gap-2"><span v-for="tag in [...entrepreneur.paymentMethods,...entrepreneur.serviceTags]" :key="tag" class="rounded-full bg-[#EAF9FC] px-3 py-1.5 text-xs font-bold text-[#0077B6]">{{ tag }}</span></div></article><article class="rounded-[26px] bg-white p-5 shadow-sm"><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Presencia digital</p><div class="mt-3 space-y-2 text-sm text-gray-500"><p><b class="text-gray-600">Instagram:</b> {{ entrepreneur.instagramUrl||'No registrado' }}</p><p><b class="text-gray-600">Facebook:</b> {{ entrepreneur.facebookUrl||'No registrado' }}</p><p><b class="text-gray-600">TikTok:</b> {{ entrepreneur.tiktokUrl||'No registrado' }}</p><p><b class="text-gray-600">Sitio web:</b> {{ entrepreneur.websiteUrl||'No registrado' }}</p></div></article></section><section class="mt-5 rounded-[28px] bg-white p-5 shadow-sm sm:p-6"><div class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-xs font-black uppercase tracking-[.15em] text-[#00B4D8]">Tus puntos de venta</p><h2 class="mt-1 text-2xl font-black">Locales y horarios</h2><p class="mt-1 text-sm text-gray-400">Puedes registrar uno o varios locales y colocar cada punto exacto en el mapa.</p></div><button class="rounded-[15px] bg-[#00B4D8] px-5 py-3 text-sm font-black text-white" @click="openLocation()">+ Agregar local</button></div><div v-if="locations.length" class="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3"><article v-for="l in locations" :key="l.id" class="rounded-[22px] bg-[#F8FBFC] p-4 ring-1 ring-gray-100"><div class="flex items-start justify-between"><div><p class="font-black">{{ l.name }}</p><p class="mt-1 text-xs text-gray-400">{{ l.isPrimary?'Local principal':'Sucursal' }}</p></div><span class="rounded-full px-2 py-1 text-[9px] font-black" :class="l.active?'bg-green-100 text-green-700':'bg-gray-100 text-gray-500'">{{ l.active?'Visible':'Oculto' }}</span></div><p class="mt-3 text-sm leading-6 text-gray-500">{{ l.address }}</p><div class="mt-3 flex gap-2"><button class="flex-1 rounded-xl bg-[#EAF9FC] px-3 py-2 text-xs font-black text-[#0077B6]" @click="openLocation(l)">Editar</button><button class="rounded-xl bg-red-50 px-3 py-2 text-xs font-black text-red-600" @click="deleteLocation(l)">Eliminar</button></div></article></div><div v-else class="mt-5 rounded-[22px] border border-dashed border-[#90E0EF] bg-[#EAF9FC]/40 p-8 text-center text-sm text-gray-500">Aún no has agregado locales.</div></section></main>
<Teleport to="body"><div v-if="showEditor" class="fixed inset-0 z-[130] flex items-end justify-center bg-black/50 sm:items-center sm:p-5" @click.self="closeEditor"><section class="max-h-[94vh] w-full overflow-y-auto rounded-t-[28px] bg-white sm:max-w-[760px] sm:rounded-[28px]"><div class="sticky top-0 z-10 flex items-center justify-between border-b bg-white px-5 py-4"><div><p class="text-xs font-black uppercase tracking-[.14em] text-[#00B4D8]">Tu negocio</p><h2 class="text-xl font-black">Editar perfil</h2></div><button class="h-9 w-9 rounded-full bg-gray-100" @click="closeEditor">×</button></div><form class="space-y-5 p-5 sm:p-6" @submit.prevent="saveProfile"><div class="flex items-center gap-4"><img v-if="logoPreview" :src="logoPreview" class="h-20 w-20 rounded-[22px] object-cover"><div v-else class="flex h-20 w-20 items-center justify-center rounded-[22px] bg-[#EAF9FC] font-black text-[#0077B6]">{{ initials }}</div><label class="cursor-pointer rounded-xl bg-[#EAF9FC] px-4 py-2 text-sm font-black text-[#0077B6]">Cambiar logo<input type="file" accept="image/*" class="hidden" @change="handleLogo"></label></div><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold">Nombre del emprendimiento<input v-model="form.businessName" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none focus:border-[#00B4D8]"></label><label class="text-sm font-bold">WhatsApp / teléfono<input v-model="form.phone" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none focus:border-[#00B4D8]"></label><label class="text-sm font-bold">Departamento<select v-model="form.department" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none"><option value="">Selecciona</option><option v-for="d in departments" :key="d">{{ d }}</option></select></label><label class="text-sm font-bold">Distrito<input v-model="form.district" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none"></label></div><label class="block text-sm font-bold">Descripción<textarea v-model="form.description" rows="4" class="mt-1 w-full rounded-xl border border-gray-200 p-4 outline-none focus:border-[#00B4D8]"></textarea></label><div><p class="text-sm font-black">Redes sociales</p><div class="mt-2 grid gap-3 sm:grid-cols-2"><input v-model="form.instagramUrl" placeholder="Instagram: usuario o URL" class="rounded-xl border border-gray-200 px-4 py-3 outline-none"><input v-model="form.facebookUrl" placeholder="Facebook: usuario o URL" class="rounded-xl border border-gray-200 px-4 py-3 outline-none"><input v-model="form.tiktokUrl" placeholder="TikTok: usuario o URL" class="rounded-xl border border-gray-200 px-4 py-3 outline-none"><input v-model="form.websiteUrl" placeholder="Sitio web" class="rounded-xl border border-gray-200 px-4 py-3 outline-none"></div></div><div><p class="text-sm font-black">Formas de pago</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="x in paymentOptions" :key="x" type="button" class="rounded-full px-3 py-2 text-xs font-bold" :class="form.paymentMethods.includes(x)?'bg-[#00B4D8] text-white':'bg-gray-100 text-gray-500'" @click="toggleArray('paymentMethods',x)">{{ x }}</button></div></div><div><p class="text-sm font-black">Servicios y condiciones</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="x in serviceOptions" :key="x" type="button" class="rounded-full px-3 py-2 text-xs font-bold" :class="form.serviceTags.includes(x)?'bg-[#00B4D8] text-white':'bg-gray-100 text-gray-500'" @click="toggleArray('serviceTags',x)">{{ x }}</button></div></div><div class="rounded-[18px] bg-[#F8FBFC] p-4"><p class="text-sm font-black">Cambiar contraseña <span class="font-normal text-gray-400">(opcional)</span></p><div class="mt-3 grid gap-2"><input v-model="currentPassword" type="password" placeholder="Contraseña actual" class="rounded-xl border border-gray-200 px-4 py-3"><input v-model="newPassword" type="password" placeholder="Nueva contraseña" class="rounded-xl border border-gray-200 px-4 py-3"><input v-model="confirmPassword" type="password" placeholder="Confirmar nueva contraseña" class="rounded-xl border border-gray-200 px-4 py-3"></div></div><button :disabled="saving" class="w-full rounded-[15px] bg-[#00B4D8] px-5 py-3.5 font-black text-white disabled:opacity-50">{{ saving?'Guardando...':'Guardar cambios' }}</button></form></section></div></Teleport>
<Teleport to="body"><div v-if="showLocationEditor" class="fixed inset-0 z-[140] flex items-end justify-center bg-black/50 sm:items-center sm:p-5" @click.self="closeLocation"><section class="max-h-[95vh] w-full overflow-y-auto rounded-t-[28px] bg-white sm:max-w-[860px] sm:rounded-[28px]"><div class="sticky top-0 z-10 flex items-center justify-between border-b bg-white px-5 py-4"><div><p class="text-xs font-black uppercase tracking-[.14em] text-[#00B4D8]">Ubicación</p><h2 class="text-xl font-black">{{ locationForm.id?'Editar local':'Agregar local' }}</h2></div><button class="h-9 w-9 rounded-full bg-gray-100" @click="closeLocation">×</button></div><div class="space-y-5 p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm font-bold">Nombre del local<input v-model="locationForm.name" placeholder="Ej. Sucursal Centro" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none"></label><label class="text-sm font-bold">Dirección<input v-model="locationForm.address" placeholder="Dirección que verá el cliente" class="mt-1 w-full rounded-xl border border-gray-200 px-4 py-3 outline-none"></label></div><LocationPicker v-model:latitude="locationForm.latitude" v-model:longitude="locationForm.longitude"/><div class="flex flex-wrap gap-4"><label class="flex items-center gap-2 text-sm font-bold"><input v-model="locationForm.isPrimary" type="checkbox"> Local principal</label><label class="flex items-center gap-2 text-sm font-bold"><input v-model="locationForm.active" type="checkbox"> Visible para clientes</label></div><div><div class="flex items-center justify-between"><p class="text-sm font-black">Horario</p><button class="text-xs font-black text-[#0077B6]" @click="locationForm.hours=emptyHours()">Restablecer horario</button></div><div class="mt-3 space-y-2"><div v-for="h in locationForm.hours" :key="h.weekday" class="grid grid-cols-[90px_1fr] items-center gap-2 rounded-[14px] bg-[#F8FBFC] p-3 sm:grid-cols-[110px_100px_1fr_1fr]"><span class="text-xs font-black">{{ weekdays[h.weekday] }}</span><label class="flex items-center gap-1 text-[10px] font-bold text-gray-500"><input v-model="h.isClosed" type="checkbox"> Cerrado</label><input v-model="h.openTime" type="time" :disabled="h.isClosed" class="rounded-lg border border-gray-200 px-2 py-2 text-xs disabled:opacity-40"><input v-model="h.closeTime" type="time" :disabled="h.isClosed" class="rounded-lg border border-gray-200 px-2 py-2 text-xs disabled:opacity-40"></div></div></div><button :disabled="locationSaving" class="w-full rounded-[15px] bg-[#00B4D8] px-5 py-3.5 font-black text-white disabled:opacity-50" @click="saveLocation">{{ locationSaving?'Guardando...':'Guardar local' }}</button></div></section></div></Teleport>
<DemoSubscriptionModal :show="showPayment" :loading="paymentLoading" :price="subscription.price" @close="closePayment" @confirm="confirmDemoPayment"/>
</div>
</template>
